package cinema.view.ui;
import java.awt.*;
import java.time.*;
import java.util.Date;
import javax.swing.*;
/** Date/time picker writes only to the existing text field; parsing/BUS remain unchanged. */
public final class DateInputs {
    private DateInputs(){}
    public static void attach(JTextField field,boolean time,boolean optional){if(field.getClientProperty("cinema.datePicker")!=null)return;field.putClientProperty("cinema.datePicker",true);JButton choose=new JButton(new Icons("calendar"));choose.putClientProperty("cinema.noIcon",true);choose.setToolTipText(time?"Chọn giờ":"Chọn ngày");choose.getAccessibleContext().setAccessibleName(choose.getToolTipText());choose.setFocusable(true);field.putClientProperty("JTextField.trailingComponent",choose);choose.addActionListener(e->{int period=field.getClientProperty("cinema.periodSelector") instanceof JComboBox<?> mode?mode.getSelectedIndex():0;LocalDate date=LocalDate.now();LocalTime hour=LocalTime.now().withSecond(0).withNano(0);try{if(!field.getText().isBlank()){if(time)hour=LocalTime.parse(field.getText().trim());else date=period==1?YearMonth.parse(field.getText().trim()).atDay(1):period==2?LocalDate.of(Integer.parseInt(field.getText().trim()),1,1):LocalDate.parse(field.getText().trim());}}catch(java.time.DateTimeException|NumberFormatException ignored){}Date value=Date.from(LocalDateTime.of(date,hour).atZone(ZoneId.systemDefault()).toInstant());JSpinner spinner=period==2&&!time?new JSpinner(new SpinnerNumberModel(date.getYear(),1000,9999,1)):new JSpinner(new SpinnerDateModel(value,null,null,time?java.util.Calendar.MINUTE:period==1?java.util.Calendar.MONTH:java.util.Calendar.DAY_OF_MONTH));if(period==2&&!time)spinner.setEditor(new JSpinner.NumberEditor(spinner,"0"));else spinner.setEditor(new JSpinner.DateEditor(spinner,time?"HH:mm":period==1?"yyyy-MM":"yyyy-MM-dd"));JPopupMenu popup=new JPopupMenu();JPanel body=new JPanel(new BorderLayout(8,12));body.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));body.add(spinner);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));JButton apply=new JButton("Áp dụng");apply.putClientProperty("cinema.role","primary");apply.addActionListener(event->{try{spinner.commitEdit();if(period==2&&!time){field.setText(spinner.getValue().toString());popup.setVisible(false);return;}LocalDateTime selected=((Date)spinner.getValue()).toInstant().atZone(ZoneId.systemDefault()).toLocalDateTime();field.setText(time?selected.toLocalTime().withSecond(0).withNano(0).toString():period==1?YearMonth.from(selected).toString():selected.toLocalDate().toString());popup.setVisible(false);}catch(java.text.ParseException error){spinner.getEditor().setBorder(new Skin.ControlBorder());}});if(optional){JButton clear=new JButton("Để trống");clear.addActionListener(event->{field.setText("");popup.setVisible(false);});actions.add(clear);}actions.add(apply);body.add(actions,BorderLayout.SOUTH);popup.add(body);Theme.apply(popup);popup.show(field,0,field.getHeight());spinner.requestFocusInWindow();});}
}
